<?php
declare(strict_types=1);
$currentPage = 'lost-items';
require_once __DIR__ . '/_bootstrap.php';
$db = get_db();
$isAdminSide = role_is_admin_side($role);
$categories = ['Electronics', 'Clothing', 'IDs & Cards', 'Accessories', 'Books & Papers', 'Others'];
$statuses = ['searching', 'matched', 'resolved'];
$error = null; $success = null;
function lost_date(string $value): bool { $date = DateTime::createFromFormat('Y-m-d', $value); return $date instanceof DateTime && $date->format('Y-m-d') === $value && $value <= date('Y-m-d'); }
function lost_status_pill(string $status): string { $map = ['searching'=>['pill--amber','Searching'],'matched'=>['pill--blue','Matched'],'resolved'=>['pill--green','Resolved']]; [$class,$label] = $map[$status] ?? ['pill--gray', ucfirst($status)]; return '<span class="pill '.$class.'">'.h($label).'</span>'; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!verify_csrf($_POST['csrf_token'] ?? null)) $error = 'Your session expired. Please try again.';
    else {
        $action = (string) ($_POST['action'] ?? '');
        try {
            if ($action === 'create') {
                $name = trim((string) ($_POST['item_name'] ?? '')); $category = (string) ($_POST['category'] ?? ''); $location = trim((string) ($_POST['last_seen_location'] ?? '')); $dateLost = (string) ($_POST['date_lost'] ?? ''); $description = trim((string) ($_POST['description'] ?? ''));
                if ($name === '' || strlen($name) > 150 || strlen($location) > 150 || strlen($description) > 1000 || !in_array($category, $categories, true) || !lost_date($dateLost)) throw new InvalidArgumentException('Enter valid item, category, date, and description details.');
                $stmt = $db->prepare('INSERT INTO lost_items (reported_by, item_name, category, last_seen_location, date_lost, description) VALUES (?, ?, ?, ?, ?, ?)'); $stmt->execute([$user['id'], $name, $category, $location ?: null, $dateLost, $description ?: null]); log_audit((int) $user['id'], 'lost_item_reported', $name); $success = 'Lost item report submitted.';
            } elseif ($action === 'update_status') {
                $id = filter_var($_POST['item_id'] ?? null, FILTER_VALIDATE_INT); $status = (string) ($_POST['new_status'] ?? ''); if (!$id || !in_array($status, $statuses, true)) throw new InvalidArgumentException('Invalid report status.');
                if ($isAdminSide) { $stmt = $db->prepare('UPDATE lost_items SET status = ? WHERE id = ?'); $stmt->execute([$status, $id]); } else { if ($status !== 'resolved') throw new InvalidArgumentException('You may only mark your own report resolved.'); $stmt = $db->prepare('UPDATE lost_items SET status = ? WHERE id = ? AND reported_by = ?'); $stmt->execute([$status, $id, $user['id']]); }
                if ($stmt->rowCount() !== 1) throw new RuntimeException('Report was not found or already had that status.'); log_audit((int) $user['id'], 'lost_item_status_changed', "item={$id} status={$status}"); $success = 'Report status updated.';
            } elseif ($action === 'delete') {
                $id = filter_var($_POST['item_id'] ?? null, FILTER_VALIDATE_INT); if (!$id) throw new InvalidArgumentException('Invalid report.');
                if ($isAdminSide) { $stmt = $db->prepare('DELETE FROM lost_items WHERE id = ?'); $stmt->execute([$id]); } else { $stmt = $db->prepare("DELETE FROM lost_items WHERE id = ? AND reported_by = ? AND status = 'searching'"); $stmt->execute([$id, $user['id']]); }
                if ($stmt->rowCount() !== 1) throw new RuntimeException('Report was not found or cannot be deleted.'); log_audit((int) $user['id'], 'lost_item_deleted', "item={$id}"); $success = 'Lost item report removed.';
            }
        } catch (InvalidArgumentException | RuntimeException $e) { $error = $e->getMessage(); } catch (Throwable $e) { $error = 'The report could not be saved. Please try again.'; }
    }
}
if ($isAdminSide) $items = $db->query('SELECT l.*, u.full_name AS reporter_name FROM lost_items l JOIN users u ON u.id = l.reported_by ORDER BY l.created_at DESC')->fetchAll();
else { $stmt = $db->prepare('SELECT l.*, u.full_name AS reporter_name FROM lost_items l JOIN users u ON u.id = l.reported_by WHERE l.reported_by = ? ORDER BY l.created_at DESC'); $stmt->execute([$user['id']]); $items = $stmt->fetchAll(); }
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Lost Items — Retrieva</title><link rel="stylesheet" href="../assets/theme.css"><link rel="stylesheet" href="styles.css"></head><body data-page="<?= h($currentPage) ?>" data-role="<?= h($role) ?>"><?php include __DIR__ . '/components/sidebar.php'; ?><div class="main-col"><?php include __DIR__ . '/components/header.php'; ?><main class="page-content"><div class="page-header"><h1>Lost Items</h1><p><?= $isAdminSide ? 'All lost item reports filed by students and faculty.' : 'Report something you lost and track its status here.' ?></p></div><?php if ($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><?php if ($success): ?><div class="alert alert-success"><?= h($success) ?></div><?php endif; ?><div class="section-title">Report a Lost Item</div><div class="card"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="create"><div class="field-row"><div class="field"><label for="item_name">Item name</label><input maxlength="150" type="text" id="item_name" name="item_name" required></div><div class="field"><label for="category">Category</label><select id="category" name="category" required><?php foreach ($categories as $category): ?><option value="<?= h($category) ?>"><?= h($category) ?></option><?php endforeach; ?></select></div></div><div class="field-row"><div class="field"><label for="last_seen_location">Last seen location</label><input maxlength="150" type="text" id="last_seen_location" name="last_seen_location"></div><div class="field"><label for="date_lost">Date lost</label><input type="date" id="date_lost" name="date_lost" max="<?= date('Y-m-d') ?>" value="<?= date('Y-m-d') ?>" required></div></div><div class="field"><label for="description">Description</label><textarea maxlength="1000" id="description" name="description"></textarea></div><button class="btn btn-primary" type="submit">Submit Report</button></form></div><div class="section-title"><?= $isAdminSide ? 'All Reports' : 'My Reports' ?></div><div class="card"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Item</th><th>Category</th><th>Last Seen</th><th>Date Lost</th><?php if ($isAdminSide): ?><th>Reported By</th><?php endif; ?><th>Status</th><th>Actions</th></tr></thead><tbody><?php if (!$items): ?><tr class="empty-row"><td colspan="<?= $isAdminSide ? 7 : 6 ?>">No lost item reports yet.</td></tr><?php endif; ?><?php foreach ($items as $item): ?><tr><td><strong><?= h($item['item_name']) ?></strong><?php if ($item['description']): ?><br><small><?= h($item['description']) ?></small><?php endif; ?></td><td><?= h($item['category']) ?></td><td><?= h($item['last_seen_location'] ?: '—') ?></td><td><?= h(date('M j, Y', strtotime($item['date_lost']))) ?></td><?php if ($isAdminSide): ?><td><?= h($item['reporter_name']) ?></td><?php endif; ?><td><?= lost_status_pill($item['status']) ?></td><td><div class="actions-cell"><?php if ($isAdminSide): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="update_status"><input type="hidden" name="item_id" value="<?= (int) $item['id'] ?>"><select name="new_status" onchange="this.form.submit()"><?php foreach ($statuses as $status): ?><option value="<?= h($status) ?>" <?= $item['status'] === $status ? 'selected' : '' ?>><?= h(ucfirst($status)) ?></option><?php endforeach; ?></select></form><?php elseif ($item['status'] !== 'resolved'): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="update_status"><input type="hidden" name="item_id" value="<?= (int) $item['id'] ?>"><input type="hidden" name="new_status" value="resolved"><button class="btn btn-sm btn-success">Mark Resolved</button></form><?php endif; ?><?php if ($isAdminSide || $item['status'] === 'searching'): ?><form method="post" onsubmit="return confirm('Delete this report?');"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="item_id" value="<?= (int) $item['id'] ?>"><button class="btn btn-sm btn-danger">Delete</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></div></main></div><script src="dashboard.js"></script></body></html>
